TLM.f("Sancti/08-30o",{"officium":"Ss. Felicis et Adaucti Martyrum","rule":["vide C3;","Gloria"],"fallback":"Commune/C3","from":{"Tractus":"Commune/C3"},"sections":{"Introitus":[{"k":"ref","la":"Eccli 44:15; 44:14"},{"k":"text","la":"Sapiéntiam Sanctórum narrent populi, et laudes eórum núntiet ecclésia: nómina autem eórum vivent in sǽculum sǽculi."},{"k":"ref","la":"Ps 32:1"},{"k":"text","la":"Exsultáte, justi, in Dómino: rectos decet collaudátio."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Sapiéntiam Sanctórum narrent populi, et laudes eórum núntiet ecclésia: nómina autem eórum vivent in sǽculum sǽculi."}],"Oratio":[{"k":"text","la":"Majestátem tuam, Dómine, súpplices exorámus: ut, sicut nos júgiter Sanctórum tuórum commemoratióne lætíficas; ita semper supplicatióne deféndas."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Sap 10:17-20"},{"k":"text","la":"Réddidit Deus justis mercédem labórum suorum, et dedúxit illos in via mirábili: et fuit illis in velaménto diéi et in luce stellárum per noctem: tránstulit illos per Mare Rubrum, et transvéxit illos per aquam nímiam. Inimícos autem illórum demérsit in mare, et ab altitúdine inferórum edúxit illos. Ideo justi tulérunt spólia impiórum, et decantavérunt, Dómine, nomen sanctum tuum, et víctricem manum tuam laudavérunt páriter, Dómine, Deus noster."}],"Graduale":[{"k":"ref","la":"Sap 3:1-2; 3:3"},{"k":"text","la":"Justórum ánimæ in manu Dei sunt: et non tanget illos torméntum malítiæ."},{"k":"text","la":"Visi sunt óculis insipiéntium mori: illi autem sunt in pace.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"text","la":"Fulgébunt justi, et tamquam scintíllæ in arundinéto discúrrent in ætérnum. Allelúja.","mark":"V"}],"Tractus":[{"k":"ref","la":"Exod 15:11"},{"k":"text","la":"Gloriósus Deus in Sanctis suis: mirábilis in majestáte, fáciens prodígia."},{"k":"ref","la":"Exod 15:6"},{"k":"text","la":"Déxtera tua, Dómine, glorificáta est in virtúte: déxtera manus tua confrégit inimícos.","mark":"V"},{"k":"ref","la":"Ps 125:5-6"},{"k":"text","la":"Qui séminant in lácrimis, in gáudio metent."},{"k":"text","la":"Eúntes ibant et flébant, mitténtes sémina sua.","mark":"V"},{"k":"text","la":"Veniéntes autem vénient cum exsultatióne, portántes manípulos suos.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 10:16-20"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Qui vos audit, me audit: et qui vos spernit, me spernit. Qui autem me spernit, spernit eum, qui misit me. Revérsi sunt autem septuagínta duo cum gáudio, dicéntes: Dómine, étiam dæmónia subiiciúntur nobis in nómine tuo. Et ait illis: Vidébam sátanam sicut fulgur de cœlo cadéntem. Ecce, dedi vobis potestátem calcándi supra serpéntes et scorpiónes, et super omnem virtútem inimíci: et nihil vobis nocébit. Verúmtamen in hoc nolíte gaudére, quia spíritus vobis subiiciúntur: gaudéte autem, quod nómina vestra scripta sunt in cœlis."}],"Offertorium":[{"k":"ref","la":"Ps 31:11"},{"k":"text","la":"Lætámini in Dómino et exsultáte, justi: et gloriámini, omnes recti corde."}],"Secreta":[{"k":"text","la":"Hóstias, Dómine, tuæ plebis inténde: et, quas in honóre Sanctórum tuórum devóta mente celébrat, profícere sibi séntiat ad salútem."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 10:27"},{"k":"text","la":"Quod dico vobis in ténebris, dícite in lúmine, dicit Dóminus: et quod in aure audítis, prædicáte super tecta."}],"Postcommunio":[{"k":"text","la":"Repléti, Dómine, munéribus sacris: quǽsumus: ut, intercedéntibus Sanctis tuis, in gratiárum semper actióne maneámus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"17ff67dea965be49":{"t":"<i>Pomolimo se</i>.\nTvoje veličanstvo, Gospodine, ponizno molimo, da nas uvijek brani po zagovoru tvojih svetih kao što nas neprestano razveseljuje njihovim spomenom.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"579868d39c234d3a":{"t":"Pogledaj, Gospodine, na darove svoga naroda, i daj mu osjetiti da mu koristi za spasenje ova žrtvena svečanost koju obavlja s pobožnom odanošću na čast tvojih svetih.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"8b4b2f83c5705576":{"t":"<i>Pomolimo se</i>.\nNasićeni svetim darovima, molimo, Gospodine, da po zagovoru tvojih svetih uvijek ustrajemo u zahvaljivanju.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
